<?php
require 'bootstrap.php';
$db = (new \App\Config\Database())->getConnection();

// Fetch the latest profit distribution
$stmt = $db->query("SELECT * FROM profit_distributions ORDER BY created_at DESC LIMIT 1");
$dist = $stmt->fetch(PDO::FETCH_ASSOC);

print_r($dist);

// Fetch payments generated by this distribution
if ($dist) {
    $stmt = $db->prepare("SELECT * FROM payment_slips WHERE notes LIKE ?");
    $stmt->execute(["%Profit distribution for period " . $dist['period_start'] . "%"]);
    $payments = $stmt->fetchAll(PDO::FETCH_ASSOC);
    echo "Payments generated:\n";
    print_r($payments);
}
